class TestIntegrationSmoke:
    """End-to-end smoke tests simulating real usage."""

    def test_generate_class_diagram_smoke(self, template_instance):
        """Generate a full class diagram from templates."""
        class_template = getattr(template_instance, "class_template", "")
        if not class_template:
            pytest.skip("No class template available")
        diagram = class_template.format(
            name="User",
            attributes="  +int id\n  +str name",
            methods="  +void login()\n  +void logout()",
        )
        assert "classDiagram" in diagram
        assert "User" in diagram
        assert "login" in diagram

    def test_generate_relationship_smoke(self, template_instance):
        """Generate a relationship snippet from the relationship map."""
        rel_map = getattr(template_instance, "relationship_map", {})
        if "inheritance" not in rel_map:
            pytest.skip("No inheritance relationship defined")
        snippet = rel_map["inheritance"].format(
            from_class="Dog",
            to_class="Animal",
            relationship="<|--",
        )
        assert "Dog" in snippet
        assert "Animal" in snippet

    def test_full_diagram_assembly(self, template_instance):
        """Assemble a complete diagram using multiple templates."""
        class_template = getattr(template_instance, "class_template", "")
        rel_map = getattr(template_instance, "relationship_map", {})
        if not class_template or "inheritance" not in rel_map:
            pytest.skip("Required templates missing")

        class_a = class_template.format(
            name="Animal",
            attributes="  +str species",
            methods="  +void eat()",
        )
        class_b = class_template.format(
            name="Dog",
            attributes="  +str breed",
            methods="  +void bark()",
        )
        rel = rel_map["inheritance"].format(
            from_class="Dog",
            to_class="Animal",
            relationship="<|--",
        )
        full_diagram = "\n".join([class_a, class_b, rel])
        assert "classDiagram" in full_diagram
        assert "Dog" in full_diagram
        assert "Animal" in full_diagram
        assert "<|--" in full_diagram


